def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_d = my.count('D')
    opp_d = op.count('D')
    last_me = my[-1]
    last_opp = op[-1]

    rounds_left = 100 - n
    if rounds_left <= 2:
        if rounds_left == 2:
            if opp_d == 0:
                return 'D'
            opp_rate = opp_d / n
            if opp_rate < 0.3:
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n == 9:
                return 'D'
            return 'C'
        else:
            if n <= 10:
                return 'C'
            return 'D'

    opp_rate = opp_d / n
    if opp_rate > 0.6 or (n >= 5 and op[-5:].count('D') >= 4):
        return 'D'

    if opp_rate < 0.3:
        if n >= 2:
            if history[-2][0] == 'C' and history[-2][1] == 'D' and history[-1][0] == 'C' and history[-1][1] == 'D':
                return 'D'
        recent_my_d = 0
        for i in range(max(0, n-2), n):
            if history[i][0] == 'D':
                recent_my_d += 1
        if recent_my_d > 0:
            return 'C'
        if last_opp == 'D':
            return 'C'
        return 'C'

    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
